link.script:
(function(w,d){
  var dl=w.dataLayer=w.dataLayer||[],done=false;
  function go(){ if(done) return; done=true; dl.push({event:'page_settled'}); }
  function idle(){ if('requestIdleCallback' in w) w.requestIdleCallback(go,{timeout:2000}); else setTimeout(go,1000); }
  if(d.readyState==='complete') idle(); else w.addEventListener('load',idle);
  ['scroll','keydown','pointerdown','touchstart'].forEach(function(t){ w.addEventListener(t,go,{once:true,passive:true}); });
  setTimeout(go,5000);
})(window,document);

body.script:
(function(){
  function tap(el){ ['mousedown','mouseup','click'].forEach(function(t){ el.dispatchEvent(new MouseEvent(t,{bubbles:true,cancelable:true,view:window})); }); }
  function init(){
    var nav=document.querySelector('.hdr-navmenu'); if(!nav) return;
    var dds=[].slice.call(nav.querySelectorAll('.w-dropdown'));
    var mqDesk=window.matchMedia('(min-width:992px)');
    var body=document.body;
    var closeTimer=null;
    function cancelTimer(){ if(closeTimer){clearTimeout(closeTimer);closeTimer=null;} }
    function openOnly(dd){
      dds.forEach(function(o){
        var t=o.querySelector('.w-dropdown-toggle'), l=o.querySelector('.w-dropdown-list');
        var on=(o===dd);
        if(t){t.classList.toggle('w--open',on);t.setAttribute('aria-expanded',on?'true':'false');}
        if(l){l.classList.toggle('w--open',on);}
      });
    }
    function activeDd(){ for(var i=0;i=r.left && x<=r.right && y>=r.top && y<=r.bottom; }
    dds.forEach(function(dd){
      dd.addEventListener('mouseenter',function(){ if(mqDesk.matches){ cancelTimer(); openOnly(dd); } });
      var toggle=dd.querySelector('.w-dropdown-toggle');
      if(toggle){ toggle.addEventListener('click',function(e){ if(!mqDesk.matches){ e.preventDefault(); e.stopPropagation(); var was=dd.classList.contains('acc-open'); dds.forEach(function(o){o.classList.remove('acc-open');}); if(!was) dd.classList.add('acc-open'); } }); }
    });
    // Top-level items without a dropdown (e.g. Pricing) close whatever is open; the mousemove
    // guard below otherwise keeps the last menu open anywhere inside the bar (bug found 2026-09-10).
    [].slice.call(nav.children).forEach(function(el){
      if(el.classList.contains('w-dropdown')) return;
      el.addEventListener('mouseenter',function(){ if(mqDesk.matches){ cancelTimer(); openOnly(null); } });
    });
    document.addEventListener('mousemove',function(e){
      if(!mqDesk.matches) return;
      var dd=activeDd(); if(!dd) return;
      var navR=nav.getBoundingClientRect();
      var listEl=dd.querySelector('.w-dropdown-list');
      var listR=listEl?listEl.getBoundingClientRect():null;
      var panel=listR?{left:listR.left,right:listR.right,top:Math.min(listR.top,navR.bottom),bottom:listR.bottom}:null;
      if(inRect(e.clientX,e.clientY,navR)||inRect(e.clientX,e.clientY,panel)){ cancelTimer(); return; }
      if(panel && e.clientY>panel.bottom){ cancelTimer(); openOnly(null); return; }
      if(!closeTimer){ closeTimer=setTimeout(function(){ openOnly(null); closeTimer=null; },200); }
    });
    var btn=document.querySelector('.w-nav-button');
    var locked = null;
    var root = document.documentElement;
    function viewportSize(){
      var vv = window.visualViewport;
      root.style.setProperty('--hdr-viewport-height', (vv ? vv.height : window.innerHeight) + 'px');
    }
    function syncDrawer(){
      var open = !!(btn && btn.classList.contains('w--open') && !mqDesk.matches);
      body.classList.toggle('hdr-open', open);
      if(open && !locked){
        locked = { x:window.scrollX, y:window.scrollY, body:body.getAttribute('style'), overflow:root.style.overflow };
        body.style.position='fixed';
        body.style.top=-locked.y+'px';
        body.style.left=-locked.x+'px';
        body.style.width='100%';
        body.style.overflow='hidden';
        root.style.overflow='hidden';
        nav.scrollTop=0;
      }else if(!open && locked){
        var old=locked; locked=null;
        if(old.body===null) body.removeAttribute('style'); else body.setAttribute('style',old.body);
        root.style.overflow=old.overflow;
        var behavior=root.style.scrollBehavior;
        root.style.scrollBehavior='auto';
        window.scrollTo(old.x,old.y);
        root.style.scrollBehavior=behavior;
      }
      if(!open) dds.forEach(function(o){o.classList.remove('acc-open');});
      viewportSize();
    }
    var touchY=0;
    document.addEventListener('touchstart',function(e){
      if(locked && e.touches.length===1) touchY=e.touches[0].clientY;
    },{passive:true});
    document.addEventListener('touchmove',function(e){
      if(!locked || e.touches.length!==1) return;
      var y=e.touches[0].clientY, dy=y-touchY; touchY=y;
      // Prevent scrolling from escaping the drawer at either boundary on iOS.
      if(!nav.contains(e.target) || (dy>0 && nav.scrollTop<=0) ||
        (dy<0 && nav.scrollTop+nav.clientHeight>=nav.scrollHeight-1)){
        e.preventDefault();
      }
    },{passive:false});
    if(btn){
      new MutationObserver(syncDrawer).observe(btn,{attributes:true,attributeFilter:['class']});
    }
    window.addEventListener('resize',syncDrawer);
    if(window.visualViewport) window.visualViewport.addEventListener('resize',viewportSize);
    window.addEventListener('pageshow',syncDrawer);
    syncDrawer();
    function closeDrawer(){ if(btn && btn.classList.contains('w--open')) btn.click(); syncDrawer(); }
    var closeBtn=nav.querySelector('.hdr-drawer-close');
    if(closeBtn) closeBtn.addEventListener('click',function(e){ e.preventDefault(); e.stopPropagation(); closeDrawer(); });
    nav.querySelectorAll('a[href]').forEach(function(a){ a.addEventListener('click',function(){ if(!mqDesk.matches){ var h=a.getAttribute('href'); if(h && h!=='#'){ closeDrawer(); } } }); });
  }
  if(document.readyState!=='loading'){init();}else{document.addEventListener('DOMContentLoaded',init);}
})();
(function(){function ready(fn){if(document.readyState!=='loading')fn();else document.addEventListener('DOMContentLoaded',fn);}ready(function(){var hdr=document.querySelector('.hdr-header');if(!hdr)return;var off=0;function setTop(){var b=hdr.querySelector('.hdr-navwrap');if(!b)return;off=Math.round(b.getBoundingClientRect().top-hdr.getBoundingClientRect().top);hdr.style.top=(-off)+'px';}function onScroll(){hdr.classList.toggle('hdr-stuck',(window.pageYOffset||window.scrollY)>off+1);}setTop();onScroll();window.addEventListener('resize',function(){setTop();onScroll();});window.addEventListener('load',function(){setTop();onScroll();});window.addEventListener('scroll',onScroll,{passive:true});if(window.ResizeObserver){new ResizeObserver(function(){setTop();}).observe(hdr);}});})();

(function(){
  function ready(fn){if(document.readyState!=='loading')fn();else document.addEventListener('DOMContentLoaded',fn);}
  function whenNear(el, fn){
    // Defer init until the strip is close to the viewport: cloning slides made Chrome fetch every
    // lazy image on the page at DOMContentLoaded (2026-09-09 Lighthouse investigation).
    if(!('IntersectionObserver' in window)){ fn(); return; }
    var io = new IntersectionObserver(function(entries){
      if(entries.some(function(e){ return e.isIntersecting; })){ io.disconnect(); fn(); }
    }, {rootMargin: '600px 0px'});
    io.observe(el);
  }
  ready(function(){
    document.querySelectorAll('.carousel-viewport').forEach(function(vp){ whenNear(vp, function(){
      var slides = [].slice.call(vp.children).filter(function(c){ return c.classList.contains('carousel-slide'); });
      if(slides.length < 2) return;
      var SETS_EACH_SIDE = 2;
      var before = document.createDocumentFragment(), after = document.createDocumentFragment();
      for(var k = 0; k < SETS_EACH_SIDE; k++){
        slides.forEach(function(s){ var c = s.cloneNode(true); c.setAttribute('aria-hidden','true'); before.appendChild(c); });
        slides.forEach(function(s){ var c = s.cloneNode(true); c.setAttribute('aria-hidden','true'); after.appendChild(c); });
      }
      vp.insertBefore(before, slides[0]);
      vp.appendChild(after);
      var setW = 0;
      function measure(){ setW = (slides[0].offsetLeft - vp.children[0].offsetLeft) / SETS_EACH_SIDE; }
      measure();
      var CENTER = SETS_EACH_SIDE * 1; // center copy index
      vp.scrollLeft = CENTER * setW;
      window.addEventListener('resize', measure);
      // ---- state flags ----
      var touching = false, down = false, raf = null;
      vp.addEventListener('touchstart', function(){ touching = true; }, {passive:true});
      vp.addEventListener('touchend', function(){ touching = false; poke(); }, {passive:true});
      vp.addEventListener('touchcancel', function(){ touching = false; poke(); }, {passive:true});
      // ---- idle re-centering (the ONLY place the strip teleports) ----
      var idleTimer = null;
      function normalize(){
        if(!setW || touching || down || raf) return;
        var lo = (CENTER - 0.5) * setW, hi = (CENTER + 0.5) * setW;
        var pos = vp.scrollLeft, next = pos;
        while(next < lo) next += setW;
        while(next >= hi) next -= setW;
        if(next !== pos) vp.scrollLeft = next;
      }
      function poke(){
        if(idleTimer) clearTimeout(idleTimer);
        idleTimer = setTimeout(normalize, 150);
      }
      vp.addEventListener('scroll', poke, {passive:true});
      // ---- mouse drag + momentum (desktop only; touch is native) ----
      var vel = 0;
      function stopFling(){ if(raf){ cancelAnimationFrame(raf); raf = null; } }
      function fling(v){
        vel = Math.max(-70, Math.min(70, v));
        stopFling();
        (function frame(){
          vp.scrollLeft += vel;
          vel *= 0.94;
          if(Math.abs(vel) > 0.4) raf = requestAnimationFrame(frame);
          else { raf = null; poke(); }
        })();
      }
      var sec = vp.closest('.carousel') || document;
      function stepDist(){ return slides[0].getBoundingClientRect().width + 32; }
      function bind(btn, dir){
        if(!btn) return;
        function go(){ fling(dir * stepDist() * 0.06); }
        btn.addEventListener('click', go);
        btn.addEventListener('keydown', function(e){ if(e.key === 'Enter' || e.key === ' '){ e.preventDefault(); go(); } });
      }
      bind(sec.querySelector('[data-carousel-prev]'), -1);
      bind(sec.querySelector('[data-carousel-next]'), 1);
      var moved = false, lastX = 0, lastT = 0, v = 0;
      vp.addEventListener('pointerdown', function(e){
        if(e.pointerType !== 'mouse' || e.button !== 0) return;
        down = true; moved = false; lastX = e.clientX; lastT = performance.now(); v = 0;
        stopFling();
      });
      window.addEventListener('pointermove', function(e){
        if(!down) return;
        var now = performance.now(), dx = e.clientX - lastX, dt = Math.max(1, now - lastT);
        if(!moved && Math.abs(dx) > 4){ moved = true; vp.classList.add('is-dragging'); }
        if(moved){
          vp.scrollLeft -= dx;
          v = 0.8 * v + 0.2 * (-dx / dt * 16.7);
          lastX = e.clientX; lastT = now;
        }
      });
      window.addEventListener('pointerup', function(){
        if(!down) return;
        down = false;
        if(moved && Math.abs(v) > 1) fling(v); else poke();
        requestAnimationFrame(function(){ vp.classList.remove('is-dragging'); moved = false; });
      });
      vp.addEventListener('click', function(e){ if(moved){ e.preventDefault(); e.stopPropagation(); } }, true);
      vp.addEventListener('dragstart', function(e){ e.preventDefault(); });
    }); });
  });
})();

(function(){
  function ready(fn){if(document.readyState!=='loading')fn();else document.addEventListener('DOMContentLoaded',fn);}
  ready(function(){
    document.querySelectorAll('.tst-viewport').forEach(function(vp){
      var slides = [].slice.call(vp.children);
      if(slides.length < 2) return;
      var sec = vp.closest('.tst') || document;
      var dots = [].slice.call(sec.querySelectorAll('.tst-dot'));
      var cur = 0;
      function slideW(){ return vp.clientWidth; }
      function paint(){
        cur = Math.max(0, Math.min(slides.length - 1, Math.round(vp.scrollLeft / slideW())));
        dots.forEach(function(d, k){ d.classList.toggle('is-on', k === cur); });
      }
      vp.addEventListener('scroll', paint, {passive:true});
      paint();
      function goTo(i){
        i = Math.max(0, Math.min(slides.length - 1, i));
        vp.scrollTo({left: i * slideW(), behavior: 'smooth'});
      }
      dots.forEach(function(d, k){
        d.addEventListener('click', function(){ goTo(k); });
        d.addEventListener('keydown', function(e){ if(e.key === 'Enter' || e.key === ' '){ e.preventDefault(); goTo(k); } });
      });
      window.addEventListener('resize', function(){ vp.scrollLeft = cur * slideW(); });
      // ---- mouse drag (touch is native scroll-snap) ----
      var down = false, moved = false, lastX = 0, lastT = 0, v = 0, settleTimer = null;
      vp.addEventListener('pointerdown', function(e){
        if(e.pointerType !== 'mouse' || e.button !== 0) return;
        down = true; moved = false; lastX = e.clientX; lastT = performance.now(); v = 0;
        if(settleTimer){ clearTimeout(settleTimer); settleTimer = null; }
      });
      window.addEventListener('pointermove', function(e){
        if(!down) return;
        var now = performance.now(), dx = e.clientX - lastX, dt = Math.max(1, now - lastT);
        if(!moved && Math.abs(dx) > 4){ moved = true; vp.classList.add('is-dragging'); }
        if(moved){
          vp.scrollLeft -= dx;
          v = 0.8 * v + 0.2 * (-dx / dt * 16.7);
          lastX = e.clientX; lastT = now;
        }
      });
      window.addEventListener('pointerup', function(){
        if(!down) return;
        down = false;
        if(moved){
          var t = vp.scrollLeft / slideW();
          var i = Math.abs(v) > 4 ? (v > 0 ? Math.ceil(t) : Math.floor(t)) : Math.round(t);
          goTo(i);
          settleTimer = setTimeout(function(){ vp.classList.remove('is-dragging'); settleTimer = null; }, 450);
        }
        moved = false;
      });
      vp.addEventListener('click', function(e){ if(vp.classList.contains('is-dragging')){ e.preventDefault(); e.stopPropagation(); } }, true);
      vp.addEventListener('dragstart', function(e){ e.preventDefault(); });
    });
  });
})();

(function(){
  function ready(fn){if(document.readyState!=='loading')fn();else document.addEventListener('DOMContentLoaded',fn);}
  function whenNear(el, fn){
    // Defer init until the strip is close to the viewport: cloning slides made Chrome fetch every
    // lazy image on the page at DOMContentLoaded (2026-09-09 Lighthouse investigation).
    if(!('IntersectionObserver' in window)){ fn(); return; }
    var io = new IntersectionObserver(function(entries){
      if(entries.some(function(e){ return e.isIntersecting; })){ io.disconnect(); fn(); }
    }, {rootMargin: '600px 0px'});
    io.observe(el);
  }
  ready(function(){
    document.querySelectorAll('.mq-row').forEach(function(row){ whenNear(row, function(){
      var kids = [].slice.call(row.children);
      if(!kids.length) return;
      kids.forEach(function(k){ var c = k.cloneNode(true); c.setAttribute('aria-hidden','true'); row.appendChild(c); });
      var half = row.scrollWidth / 2;
      row.style.setProperty('--mq-dur', Math.max(20, Math.round(half / 40)) + 's');
      row.classList.add('is-ready');
    }); });
  });
})();

(function(){
  function ready(fn){if(document.readyState!=='loading')fn();else document.addEventListener('DOMContentLoaded',fn);}
  ready(function(){
    document.querySelectorAll('.faq .faq-q').forEach(function(q){
      var item=q.closest('.faq-item'), ans=item&&item.querySelector('.faq-a');
      if(!item||!ans) return;
      function toggle(){
        var open=item.classList.toggle('is-open');
        q.setAttribute('aria-expanded',open?'true':'false');
        ans.style.maxHeight=open?ans.scrollHeight+'px':'0px';
      }
      q.addEventListener('click',toggle);
      q.addEventListener('keydown',function(e){ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); toggle(); } });
    });
    window.addEventListener('resize',function(){
      document.querySelectorAll('.faq .faq-item.is-open .faq-a').forEach(function(a){ a.style.maxHeight=a.scrollHeight+'px'; });
    });
  });
})();

(function(){
  function ready(fn){if(document.readyState!=='loading')fn();else document.addEventListener('DOMContentLoaded',fn);}
  ready(function(){
    document.querySelectorAll('[data-ll-roislider]').forEach(function(w){
      var input = w.querySelector('input[type="range"]');
      if(!input) return;
      var min = parseInt(w.getAttribute('data-min'), 10); if(isNaN(min)) min = parseInt(input.min, 10) || 0;
      var max = parseInt(w.getAttribute('data-max'), 10); if(isNaN(max)) max = parseInt(input.max, 10) || 10000;
      var prefix = w.getAttribute('data-prefix') || '$';
      var fill = w.querySelector('[data-roi="fill"]');
      var handle = w.querySelector('[data-roi="handle"]');
      var uplift = w.querySelector('[data-roi="uplift"]');
      var orders = w.querySelector('[data-roi="orders"]');
      input.min = min; input.max = max;
      var start = parseInt(input.value, 10);
      if(isNaN(start) || start < min || start > max) input.value = min;
      if(handle) handle.style.transform = 'translateX(-50%)';
      function upliftFor(v){
        if(v === 0) return '0';
        var averageOrderValue = 50, annualPurchaseFrequency = 2, lifetimePurchases = 4;
        var annualSpendAllShoppers = averageOrderValue * annualPurchaseFrequency;
        var annualSpendRedeemingMember = annualSpendAllShoppers * (1 + 1.6445);
        var annualSpendMember = annualSpendAllShoppers * (1 + 0.3997);
        var shoppers = (v / annualPurchaseFrequency) * 12;
        var members = shoppers * 0.3446;
        var newRedeemingMembersPerYear = members * 0.2324;
        var revenueCoreLoyalty = (annualSpendRedeemingMember - annualSpendMember) * newRedeemingMembersPerYear;
        var revenueCoreReferrals = 250 * averageOrderValue * lifetimePurchases;
        var n = Math.round(revenueCoreLoyalty + revenueCoreReferrals);
        return n >= 1000000 ? (n / 1000000).toFixed(2) + ' mil' : n.toLocaleString();
      }
      function paint(){
        var v = parseInt(input.value, 10) || 0;
        var atMax = (v === max);
        var pct = (max > min) ? (v - min) / (max - min) : 0;
        if(fill) fill.style.width = (pct * 100) + '%';
        if(handle) handle.style.left = (pct * 100) + '%';
        if(orders) orders.textContent = (atMax ? Math.round(max / 1000) + 'k+' : v.toLocaleString()) + ' monthly orders';
        if(uplift) uplift.textContent = prefix + upliftFor(v) + (atMax && v !== 0 ? '+' : '');
      }
      paint();
      input.addEventListener('input', paint);
    });
  });
})();

(function(){
  if(document.querySelector('main,[role="main"]')) return;
  var b=document.body, kids=[].slice.call(b.children);
  var h=kids.filter(function(e){ return e.matches('header,.hdr-header'); })[0];
  var f=kids.filter(function(e){ return e.matches('footer,.ftr-footer'); }).pop();
  if(!h||!f) return;
  var m=document.createElement('main'), n=h.nextSibling, moved=[];
  while(n&&n!==f){ moved.push(n); n=n.nextSibling; }
  if(!moved.length) return;
  b.insertBefore(m,f);
  moved.forEach(function(x){ m.appendChild(x); });
})();
